/**
 * A date *field* with segmented entry and a calendar popup (`design/components/date-picker.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/date-picker.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/popover'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Icon,
  agentDate,
  agentDateTime,
  agentMember,
  anchorProps,
  calendarDateOf,
  claimSlot,
  createCell,
  createDerived,
  dateFieldDraft,
  dateFieldValue,
  dateOutOfBounds,
  elementRef,
  eraseSegment,
  fieldSegments,
  itemOf,
  mergeParts,
  scope,
  stepSegment,
  syncTriggerAnchor,
  typeIntoSegment,
  useDirection,
  useMachine,
  useMediaQuery,
  watchEffect,
  type CalendarDateTime,
  type Defaults,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/controls/date-picker.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'
import Button from './Button'
import Calendar, { type CalendarDate, type CalendarMessages } from './Calendar'

export type DatePickerMessages = CalendarMessages & {
  showCalendar: string
  clear: string
  chooseDate: string
}

export interface DatePickerProps {
  'aria-describedby'?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * Input's clear button. Clearing returns the segments to their placeholders.
   */
  clearable?: boolean
  /**
   * Opens on mount, for galleries and tests. Screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: CalendarDate | null | CalendarDateTime
  disabled?: boolean
  firstDayOfWeek?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  granularity?: 'day' | 'hour' | 'minute'
  id?: string
  invalid?: boolean
  isDateUnavailable?: (date: CalendarDate) => boolean
  /**
   * Orders the segments as well as naming the months.
   */
  locale?: string
  maxValue?: CalendarDate
  /**
   * Defaults to generic English. Localized hosts pass strings from their catalog.
   */
  messages?: DatePickerMessages
  minValue?: CalendarDate
  /**
   * Serializes ISO-8601, at the granularity.
   */
  name?: string
  onChange?: ((value: CalendarDate | null) => void) | ((value: CalendarDateTime | null) => void)
  /**
   * `'auto'` shows the popup as a sheet below `30rem` (the conventions' sheet presentation),
   * with Calendar unchanged inside it. `'popover'` keeps the popover at every width. There is no
   * always-sheet value (`docs/layout.md`). The segments stay the primary input at every width,
   * and the field itself never becomes a sheet.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * `CalendarDateTime`: the same package's datetime type, without a time zone, never a JS `Date`
   * (Calendar's law). The value type follows the granularity, and React Aria enforces the match
   * at runtime instead of inventing a midnight time.
   */
  value?: CalendarDate | null | CalendarDateTime
}

/** A date *field* with segmented entry and a calendar popup. */
export default function DatePicker(given: DatePickerProps): JSX.Element {
  const props = mergeProps(
    {
      granularity: 'day',
      clearable: false,
      size: 'md',
      disabled: false,
      invalid: false,
      presentation: 'auto',
    } as Defaults<
      DatePickerProps,
      'granularity' | 'clearable' | 'size' | 'disabled' | 'invalid' | 'presentation'
    >,
    claimSlot(given, 'group'),
  )
  return scope(() => {
    const uid = createUniqueId()
    const browserLanguage = createCell(undefined as string | undefined)
    const draft = createCell(
      dateFieldDraft(props.value !== undefined ? props.value : props.defaultValue, {
        locale: props.locale ?? browserLanguage.value ?? 'en-US',
        parts:
          props.granularity === 'minute'
            ? (['year', 'month', 'day', 'hour', 'minute'] as const)
            : props.granularity === 'hour'
              ? (['year', 'month', 'day', 'hour'] as const)
              : (['year', 'month', 'day'] as const),
      }),
    )
    const typed = createCell('')
    const reported = createCell(
      (props.value !== undefined ? props.value : props.defaultValue)?.toString() ?? '',
    )
    const anchor = elementRef<HTMLElement>()
    const field = elementRef<HTMLElement>()
    const panel = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const sheetPanel = elementRef<HTMLElement>()
    const phone = useMediaQuery('phone')
    const say = createDerived(
      () =>
        props.messages ?? {
          previousMonth: 'Previous month',
          nextMonth: 'Next month',
          showCalendar: 'Show calendar',
          clear: 'Clear',
          chooseDate: 'Choose a date',
        },
    )
    const language = createDerived(() => props.locale ?? browserLanguage.value ?? 'en-US')
    const sheeting = createDerived(() => props.presentation === 'auto' && phone())
    const fieldOptions = createDerived(() => ({
      locale: language.value,
      parts:
        props.granularity === 'minute'
          ? (['year', 'month', 'day', 'hour', 'minute'] as const)
          : props.granularity === 'hour'
            ? (['year', 'month', 'day', 'hour'] as const)
            : (['year', 'month', 'day'] as const),
    }))
    const segments = createDerived(() => fieldSegments(draft.value, fieldOptions.value))
    const kept = createDerived(
      () => (props.value !== undefined ? props.value : props.defaultValue) ?? null,
    )
    const current = createDerived(() => dateFieldValue(draft.value, fieldOptions.value, kept.value))
    const fieldInvalid = createDerived(
      () =>
        props.invalid ||
        dateOutOfBounds(current.value, {
          min: props.minValue,
          max: props.maxValue,
          unavailable: props.isDateUnavailable,
        }),
    )
    const showClear = createDerived(
      () => props.clearable && current.value !== null && !props.disabled,
    )
    const commit = createDerived(() => (next: ReturnType<typeof dateFieldDraft>): void => {
      draft.value = next
      const after = dateFieldValue(next, fieldOptions.value, kept.value)
      const text = after?.toString() ?? ''
      if (text !== reported.value) {
        reported.value = text
        ;(props.onChange as unknown as ((...args: unknown[]) => unknown) | undefined)?.(after)
      }
    })
    const clear = createDerived(() => (): void => {
      commit.value({})
      field.value?.querySelector<HTMLElement>('[data-segment]')?.focus()
    })
    const segmentName = createDerived(() => (type: string): string => {
      try {
        return new Intl.DisplayNames(language.value, { type: 'dateTimeField' }).of(type) ?? type
      } catch {
        return type
      }
    })
    const moveSegment = createDerived(() => (from: EventTarget | null, step: number): void => {
      if (!(from instanceof HTMLElement)) return
      const all = [
        ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
      ]
      all[all.indexOf(from) + step]?.focus()
    })
    const segmentInput = createDerived(
      () =>
        (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
          event.preventDefault()
          if (segment.type === 'literal' || !!props.disabled) return
          const data = (event as InputEvent).data ?? ''
          for (const key of data) {
            const next = typeIntoSegment(
              draft.value,
              segment.type,
              typed.value,
              key,
              fieldOptions.value,
            )
            typed.value = next.typed
            commit.value(next.draft)
            if (next.advance) {
              moveSegment.value(event.currentTarget, 1)
              break
            }
          }
        },
    )
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          defaultOpen: props.defaultOpen,
          modal: sheeting.value,
          positioning: { placement: 'bottom-end' as const, offset: { mainAxis: 2 } },
          ids: props.id === undefined ? undefined : { anchor: props.id },
          initialFocusEl: () =>
            (sheetPanel.value ?? panel.value)?.querySelector<HTMLElement>('[tabindex="0"]') ?? null,
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const choose = createDerived(() => (date: CalendarDate | null): void => {
      if (date === null) return
      commit.value({ ...draft.value, year: date.year, month: date.month, day: date.day })
      api.value.setOpen(false)
    })
    const segmentKeys = createDerived(
      () =>
        (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
          if (segment.type === 'literal') return
          if (event.altKey && event.key === 'ArrowDown') {
            event.preventDefault()
            if (!props.disabled) api.value.setOpen(true)
            return
          }
          if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
            event.preventDefault()
            typed.value = ''
            moveSegment.value(
              event.currentTarget,
              (event.key === 'ArrowRight') ===
                (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
                ? 1
                : -1,
            )
            return
          }
          if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
          const editable = !props.disabled
          if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
            event.preventDefault()
            typed.value = ''
            if (editable)
              commit.value(
                stepSegment(
                  draft.value,
                  segment.type,
                  event.key === 'ArrowUp' ? 1 : -1,
                  fieldOptions.value,
                ),
              )
            return
          }
          if (event.key === 'Backspace' || event.key === 'Delete') {
            event.preventDefault()
            typed.value = ''
            if (!editable) return
            if (draft.value[segment.type] === undefined) moveSegment.value(event.currentTarget, -1)
            else commit.value(eraseSegment(draft.value, segment.type, fieldOptions.value))
            return
          }
          if (event.key.length !== 1) return
          event.preventDefault()
          if (editable)
            ((key: string): void => {
              const next = typeIntoSegment(
                draft.value,
                segment.type,
                typed.value,
                key,
                fieldOptions.value,
              )
              typed.value = next.typed
              commit.value(next.draft)
              if (next.advance) moveSegment.value(event.currentTarget, 1)
            })(event.key)
        },
    )
    const present = usePresence(
      () => api.value.open && !sheeting.value,
      () => panel.value,
    )
    const sheetPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => sheetPanel.value,
      'sheet.panel',
      { sheetSide: 'bottom' },
    )
    const scrimPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => scrim.value,
      'dialog.scrim',
    )
    const effect1 = () => {
      void ((browserLanguage.value = globalThis.navigator?.language),
      props.locale === undefined &&
        (draft.value = dateFieldDraft(
          props.value !== undefined ? props.value : props.defaultValue,
          {
            locale: props.locale ?? browserLanguage.value ?? 'en-US',
            parts:
              props.granularity === 'minute'
                ? (['year', 'month', 'day', 'hour', 'minute'] as const)
                : props.granularity === 'hour'
                  ? (['year', 'month', 'day', 'hour'] as const)
                  : (['year', 'month', 'day'] as const),
          },
        )))
    }
    onMount(effect1)
    const effect2 = () => {
      syncTriggerAnchor(anchor.value, api.value.getTriggerProps(), api.value.open)
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect2,
      true,
    )
    const effect3 = () => {
      void (
        props.value !== undefined &&
        (props.value !== null || current.value !== null) &&
        ((draft.value = dateFieldDraft(props.value, fieldOptions.value)),
        (reported.value = props.value?.toString() ?? ''))
      )
    }
    watchEffect(
      createMemo(() => props.value),
      effect3,
      false,
    )
    let release4: (() => void) | undefined
    const effect4 = () => {
      release4?.()
      const ran = agentMember({
        member: 'DatePicker',
        element: () => field.value,
        state: () => ({
          value: current.value?.toString() ?? '',
          open: api.value.open,
          disabled: props.disabled,
          invalid: fieldInvalid.value,
        }),
        actions: {
          set: {
            argument: 'text',
            run: (value) =>
              (() => {
                const bounds = {
                  min: props.minValue,
                  max: props.maxValue,
                  unavailable: props.isDateUnavailable,
                }
                commit.value(
                  dateFieldDraft(
                    props.granularity === 'day'
                      ? agentDate(value, bounds)
                      : agentDateTime(value, bounds, props.granularity),
                    fieldOptions.value,
                  ),
                )
              })(),
          },
          clear: () => commit.value({}),
          open: () => api.value.setOpen(true),
          close: () => api.value.setOpen(false),
        },
        withholds: () => [field.value, sheetPanel.value ?? panel.value],
      })
      release4 = () => {
        ran()
      }
    }
    onMount(effect4)
    onCleanup(() => release4?.())
    return (
      <>
        {/* field */}
        <div
          {...mergeParts(api.value.getAnchorProps(), {
            class: styles.field,
            role: 'group',
            'aria-label': props['aria-label'],
            'aria-labelledby': props['aria-labelledby'],
            'aria-describedby': props['aria-describedby'],
            'aria-disabled': props.disabled ? 'true' : undefined,
            'data-size': props.size,
            'data-disabled': props.disabled ? '' : undefined,
            'data-invalid': fieldInvalid.value ? '' : undefined,
            'data-state': api.value.open ? 'open' : 'closed',
            'data-member': 'date-picker',
          })}
          ref={field.attach}
        >
          {/* segments */}
          <div class={styles.segments} data-size={props.size}>
            <Each of={segments.value} by={(segment, at) => `date-${segment.type}-${at}`} renew>
              {(segment) => (
                <>
                  {segment.type === 'literal' ? (
                    <span class={styles.separator} aria-hidden="true">
                      {segment.text}
                    </span>
                  ) : (
                    <div
                      class={styles.segment}
                      role="spinbutton"
                      id={`${uid}-date-${segment.type}`}
                      aria-label={segmentName.value(segment.type)}
                      aria-labelledby={
                        props['aria-labelledby']
                          ? `${props['aria-labelledby']} ${uid}-date-${segment.type}`
                          : undefined
                      }
                      aria-describedby={props['aria-describedby']}
                      aria-valuenow={segment.placeholder ? undefined : segment.value}
                      aria-valuemin={segment.min}
                      aria-valuemax={segment.max}
                      aria-valuetext={segment.placeholder ? 'Empty' : segment.text}
                      aria-required={props['aria-required'] ? 'true' : undefined}
                      aria-disabled={props.disabled ? 'true' : undefined}
                      aria-invalid={fieldInvalid.value ? 'true' : undefined}
                      contenteditable={!props.disabled ? 'true' : undefined}
                      inputmode={segment.type === 'dayPeriod' ? undefined : 'numeric'}
                      spellcheck="false"
                      tabindex={props.disabled ? undefined : '0'}
                      data-segment={segment.type}
                      data-placeholder={segment.placeholder ? '' : undefined}
                      data-disabled={props.disabled ? '' : undefined}
                      onfocus={() => (typed.value = '')}
                      onkeydown={($event: KeyboardEvent) =>
                        segmentKeys.value($event, itemOf(segment))
                      }
                      onbeforeinput={($event: InputEvent) =>
                        segmentInput.value($event, itemOf(segment))
                      }
                    >
                      {segment.text}
                    </div>
                  )}
                </>
              )}
            </Each>
          </div>
          {props.name !== undefined ? (
            <input
              type="hidden"
              name={props.name}
              value={current.value?.toString() ?? ''}
              disabled={props.disabled ? true : undefined}
            />
          ) : null}
          {showClear.value ? (
            <button
              class={styles.clear}
              type="button"
              aria-label={say.value.clear}
              onclick={() => clear.value()}
            >
              <Icon name="clear" size={props.size} />
            </button>
          ) : null}
          {/* trigger */}
          <span
            {...mergeParts(anchorProps(api.value.getTriggerProps()), {
              class: triggerAnchor.anchor,
            })}
            ref={anchor.attach}
          >
            <Button
              variant="ghost"
              tone="neutral"
              size={props.size}
              iconOnly={true}
              icon="calendar"
              label={say.value.showCalendar}
              disabled={props.disabled}
            />
          </span>
        </div>
        <Portal>
          {present() ? (
            <div {...mergeParts(api.value.getPositionerProps())}>
              {/* panel */}
              <div
                {...mergeParts(api.value.getContentProps(), {
                  class: styles.content,
                  style: { '--radix-popover-content-transform-origin': 'var(--transform-origin)' },
                  hidden: undefined,
                  'aria-labelledby': undefined,
                  'aria-describedby': undefined,
                  'aria-label': say.value.chooseDate,
                  'data-member': 'date-picker',
                })}
                ref={panel.attach}
              >
                <Calendar
                  value={current.value === null ? null : calendarDateOf(current.value)}
                  minValue={props.minValue}
                  maxValue={props.maxValue}
                  isDateUnavailable={props.isDateUnavailable}
                  locale={language.value}
                  firstDayOfWeek={props.firstDayOfWeek}
                  messages={say.value}
                  aria-label={say.value.chooseDate}
                  onChange={($event) => choose.value($event)}
                />
              </div>
            </div>
          ) : null}
          {scrimPresent() ? (
            <div
              class={sheet.scrim}
              data-state={api.value.open ? 'open' : 'closed'}
              ref={scrim.attach}
            />
          ) : null}
          {sheetPresent() ? (
            <div class={sheet.positioner}>
              <div
                {...mergeParts(api.value.getContentProps(), {
                  class: sheet.panel,
                  hidden: undefined,
                  'aria-labelledby': undefined,
                  'aria-describedby': undefined,
                  'aria-label': say.value.chooseDate,
                  'aria-modal': 'true',
                  'data-presentation': 'sheet',
                })}
                ref={sheetPanel.attach}
              >
                {/* sheetBody */}
                <div class={styles.sheetBody} data-member="date-picker">
                  <Calendar
                    value={current.value === null ? null : calendarDateOf(current.value)}
                    minValue={props.minValue}
                    maxValue={props.maxValue}
                    isDateUnavailable={props.isDateUnavailable}
                    locale={language.value}
                    firstDayOfWeek={props.firstDayOfWeek}
                    messages={say.value}
                    aria-label={say.value.chooseDate}
                    onChange={($event) => choose.value($event)}
                  />
                </div>
              </div>
            </div>
          ) : null}
        </Portal>
      </>
    )
  })
}

DatePicker.controlKind = 'group'
